insert into place_terms (slug, vertical, phrase, title, match, served, landing_slug, intent_note, faq, sort_order) values
  ('dui-car-rental', 'rental', 'DUI car rental', 'DUI Car Rental', '{}', 'yes', null, 'Drivers with a DUI or a bad driving record can rent with us. Your eligibility and any deposit are confirmed when you book. A valid {{licence}} licence is required for the whole rental.', '[{"question": "Can I rent a car with a DUI on my record?", "answer": "Drivers with a DUI or a bad driving record can rent with us. Your eligibility and any deposit are confirmed when you book."}]', 400),
  ('car-rental-after-impaired-driving-conviction', 'rental', 'car rental after impaired driving conviction', 'Car Rental After an Impaired Driving Conviction', '{}', 'yes', null, 'Drivers with an impaired driving conviction can rent with us once their licence is valid again. Your eligibility and any deposit are confirmed when you book.', '[{"question": "Can I rent after an impaired driving conviction?", "answer": "Yes, with a valid licence for the whole rental. Your eligibility and any deposit are confirmed when you book."}]', 410),
  ('car-rental-with-bad-driving-record', 'rental', 'car rental with bad driving record', 'Car Rental With a Bad Driving Record', '{}', 'yes', null, 'Drivers with a DUI or a bad driving record can rent with us. Your eligibility and any deposit are confirmed when you book.', '[{"question": "Do you rent to drivers with tickets or accidents on their record?", "answer": "Drivers with a DUI or a bad driving record can rent with us. Your eligibility and any deposit are confirmed when you book."}]', 420),
  ('high-risk-driver-car-rental', 'rental', 'high risk driver car rental', 'High Risk Driver Car Rental', '{}', 'yes', null, 'Drivers that insurers call high risk can rent with us. Your eligibility and any deposit are confirmed when you book, and you see the full price before you pay.', '[{"question": "Will I pay more as a high risk driver?", "answer": "Your offer shows the full price, the deposit and the coverage before you pay anything. Nothing is charged when you send a request."}]', 430),
  ('car-rental-with-demerit-points', 'rental', 'car rental with demerit points', 'Car Rental With Demerit Points', '{}', 'yes', null, 'Demerit points on your licence do not stop you from sending a request. Your eligibility and any deposit are confirmed when you book. A valid {{licence}} licence is required.', '[{"question": "Can I rent with demerit points?", "answer": "Yes, you can send a request with a valid licence. Your eligibility and any deposit are confirmed when you book."}]', 440),
  ('car-rental-after-licence-reinstatement', 'rental', 'car rental after licence reinstatement', 'Car Rental After Licence Reinstatement', '{}', 'yes', null, 'Once your licence is reinstated and valid again, you can rent with us. A valid licence is required for the whole rental: a suspended licence cannot rent. Your eligibility and any deposit are confirmed when you book.', '[{"question": "My licence was suspended. When can I rent?", "answer": "As soon as it is reinstated and valid. A valid licence is required for the whole rental."}]', 450),
  ('uber-rental-car', 'rental', 'Uber rental car', 'Rental Car for Uber Drivers', '{}', 'yes', null, 'Use your rental for Uber work. Tell us when you book. Weekly and monthly rates first: trips of {{weekFrom}} days or more use the weekly rate, and one booking runs up to {{maxDays}} days and renews. Uber, Lyft, Uber Eats, DoorDash, SkipTheDishes, Instacart and Hopp are named only to describe the work; CarmaCars is not affiliated with, approved or endorsed by any of them.', '[{"question": "Is there a weekly or monthly rate?", "answer": "Yes. Trips of {{weekFrom}} days or more use the weekly rate, and a booking of up to {{maxDays}} days never costs more than the monthly rate. Each car shows its rates on its page."}, {"question": "Can I use the car for Uber work?", "answer": "Yes. Tell us when you book. CarmaCars is not affiliated with or approved by the companies named on this page."}]', 460),
  ('lyft-rental-car', 'rental', 'Lyft rental car', 'Rental Car for Lyft Drivers', '{}', 'yes', null, 'Use your rental for Lyft work. Tell us when you book. Weekly and monthly rates first: trips of {{weekFrom}} days or more use the weekly rate, and one booking runs up to {{maxDays}} days and renews. Uber, Lyft, Uber Eats, DoorDash, SkipTheDishes, Instacart and Hopp are named only to describe the work; CarmaCars is not affiliated with, approved or endorsed by any of them.', '[{"question": "Is there a weekly or monthly rate?", "answer": "Yes. Trips of {{weekFrom}} days or more use the weekly rate, and a booking of up to {{maxDays}} days never costs more than the monthly rate. Each car shows its rates on its page."}, {"question": "Can I use the car for Lyft work?", "answer": "Yes. Tell us when you book. CarmaCars is not affiliated with or approved by the companies named on this page."}]', 470),
  ('rideshare-car-rental', 'rental', 'rideshare car rental', 'Rideshare Car Rental', '{}', 'yes', null, 'Use your rental for Uber, Lyft or other rideshare work. Tell us when you book. Weekly and monthly rates first: trips of {{weekFrom}} days or more use the weekly rate, and one booking runs up to {{maxDays}} days and renews. Uber, Lyft, Uber Eats, DoorDash, SkipTheDishes, Instacart and Hopp are named only to describe the work; CarmaCars is not affiliated with, approved or endorsed by any of them.', '[{"question": "Is there a weekly or monthly rate?", "answer": "Yes. Trips of {{weekFrom}} days or more use the weekly rate, and a booking of up to {{maxDays}} days never costs more than the monthly rate. Each car shows its rates on its page."}, {"question": "Can I use the car for Uber, Lyft or other rideshare work?", "answer": "Yes. Tell us when you book. CarmaCars is not affiliated with or approved by the companies named on this page."}]', 480),
