  ('hopp-car-rental', 'rental', 'Hopp car rental', 'Car Rental for Hopp Drivers', '{}', 'yes', null, 'Use your rental for Hopp work. Tell us when you book. Weekly and monthly rates first: trips of {{weekFrom}} days or more use the weekly rate, and one booking runs up to {{maxDays}} days and renews. Uber, Lyft, Uber Eats, DoorDash, SkipTheDishes, Instacart and Hopp are named only to describe the work; CarmaCars is not affiliated with, approved or endorsed by any of them.', '[{"question": "Is there a weekly or monthly rate?", "answer": "Yes. Trips of {{weekFrom}} days or more use the weekly rate, and a booking of up to {{maxDays}} days never costs more than the monthly rate. Each car shows its rates on its page."}, {"question": "Can I use the car for Hopp work?", "answer": "Yes. Tell us when you book. CarmaCars is not affiliated with or approved by the companies named on this page."}]', 530),
  ('delivery-driver-car-rental', 'rental', 'delivery driver car rental', 'Delivery Driver Car Rental', '{}', 'yes', null, 'Use your rental for Uber Eats, DoorDash or other delivery work. Tell us when you book. Weekly and monthly rates first: trips of {{weekFrom}} days or more use the weekly rate, and one booking runs up to {{maxDays}} days and renews. Uber, Lyft, Uber Eats, DoorDash, SkipTheDishes, Instacart and Hopp are named only to describe the work; CarmaCars is not affiliated with, approved or endorsed by any of them.', '[{"question": "Is there a weekly or monthly rate?", "answer": "Yes. Trips of {{weekFrom}} days or more use the weekly rate, and a booking of up to {{maxDays}} days never costs more than the monthly rate. Each car shows its rates on its page."}, {"question": "Can I use the car for Uber Eats, DoorDash or other delivery work?", "answer": "Yes. Tell us when you book. CarmaCars is not affiliated with or approved by the companies named on this page."}]', 540),
  ('gig-driver-car-rental', 'rental', 'gig driver car rental', 'Gig Driver Car Rental', '{}', 'yes', null, 'Use your rental for Uber, Lyft or delivery work. Tell us when you book. Weekly and monthly rates first: trips of {{weekFrom}} days or more use the weekly rate, and one booking runs up to {{maxDays}} days and renews. Uber, Lyft, Uber Eats, DoorDash, SkipTheDishes, Instacart and Hopp are named only to describe the work; CarmaCars is not affiliated with, approved or endorsed by any of them.', '[{"question": "Is there a weekly or monthly rate?", "answer": "Yes. Trips of {{weekFrom}} days or more use the weekly rate, and a booking of up to {{maxDays}} days never costs more than the monthly rate. Each car shows its rates on its page."}, {"question": "Can I use the car for Uber, Lyft or delivery work?", "answer": "Yes. Tell us when you book. CarmaCars is not affiliated with or approved by the companies named on this page."}]', 550),
  ('g2-driver-car-rental', 'rental', 'G2 driver car rental', 'Car Rental for G2 Drivers', '{}', 'yes', null, 'We accept Ontario G2 and G licences, valid for the whole rental. Drivers {{minAge}} and older can rent; drivers under {{fullAge}} pay a young driver fee.', '[{"question": "Can I rent with a G2?", "answer": "Yes. We accept Ontario G2 and G licences. The licence has to be valid for the whole rental."}]', 560),
  ('new-driver-car-rental', 'rental', 'new driver car rental', 'Car Rental for New Drivers', '{}', 'yes', null, 'New drivers with an Ontario G2 or G licence can rent. Drivers {{minAge}} and older; drivers under {{fullAge}} pay a young driver fee for each day.', '[{"question": "I just got my licence. Can I rent?", "answer": "Yes, with an Ontario G2 or G licence valid for the whole rental. Your eligibility is confirmed when you book."}]', 570),
  ('newcomer-to-canada-car-rental', 'rental', 'newcomer to Canada car rental', 'Car Rental for Newcomers to Canada', '{}', 'yes', null, 'New to Canada? Send a request with the licence you have. Licences from outside Ontario are reviewed by a person before we confirm, and we tell you what we need.', '[{"question": "Can I rent with a licence from my home country?", "answer": "Possibly. Licences from outside Ontario are reviewed by a person before we confirm. Choose Something else in the request and we will tell you."}]', 580),
  ('international-student-car-rental', 'rental', 'international student car rental', 'Car Rental for International Students', '{}', 'yes', null, 'International students can send a request with their licence. Licences from outside Ontario are reviewed by a person before we confirm. Drivers under {{fullAge}} pay a young driver fee.', '[{"question": "Can an international student rent a car?", "answer": "Yes, with a licence we can accept. Licences from outside Ontario are reviewed by a person before we confirm."}]', 590),
  ('international-licence-car-rental', 'rental', 'international licence car rental', 'Car Rental With an International Licence', '{}', 'yes', null, 'Licences from outside Ontario, international ones included, are reviewed by a person before we confirm. Send a request and we reply with what we need.', '[{"question": "Do you accept an international driving permit?", "answer": "Licences from outside Ontario are reviewed by a person before we confirm. Send a request with your licence and permit and we will tell you."}]', 600),
  ('no-credit-check-car-rental', 'rental', 'no credit check car rental', 'Car Rental With No Credit Check', '{}', 'yes', null, 'Renting is not a loan: we check your licence, your identity and how the car is covered before we confirm. A card in your name pays and holds the deposit.', '[{"question": "What do you check before I rent?", "answer": "Your licence, your identity and how the car is covered. Your eligibility and any deposit are confirmed when you book."}]', 610),
  ('debit-card-car-rental', 'rental', 'debit card car rental', 'Car Rental With a Debit Card', '{"flags": ["no_credit_card"]}', 'yes', 'no-credit-card', 'Only the cars marked "no credit card needed" are listed: on those, a debit card in your name pays and holds the deposit.', '[{"question": "Can I pay with a debit card?", "answer": "On the cars marked no credit card needed, yes: a debit card in your name pays and holds the deposit. Other cars need a credit card."}]', 620),
  ('wedding-car-rental', 'rental', 'wedding car rental', 'Wedding Car Rental', '{"classes": ["premium", "luxury", "exotic"]}', 'yes', null, 'Premium, luxury and exotic cars for the day, delivered to the venue or picked up. Need a driver too? Our chauffeur service books one by the hour.', '[{"question": "Can the car come with a driver?", "answer": "Yes, through our chauffeur service, booked by the hour. Or rent the car and drive it yourself."}]', 630),
  ('prom-car-rental', 'rental', 'prom car rental', 'Prom Car Rental', '{"classes": ["premium", "luxury", "exotic"]}', 'yes', null, 'Premium and luxury cars for prom night. Drivers {{minAge}} and older can rent; for younger guests, our chauffeur service books a driver by the hour.', '[{"question": "Can a student rent for prom?", "answer": "Drivers {{minAge}} and older with a valid licence can rent. For a driver, book our chauffeur service."}]', 640),
  ('photoshoot-car-rental', 'rental', 'photoshoot or film car rental', 'Car Rental for Photoshoots and Film', '{"classes": ["premium", "luxury", "exotic"]}', 'yes', null, 'Luxury and exotic cars for a shoot or a film day. Tell us the location and how the car will be used in your request, and we confirm before you pay.', '[{"question": "Can I use the car in a photoshoot or film?", "answer": "Tell us in your request how the car will be used and where. We confirm before you pay."}]', 650),
  ('road-trip-car-rental', 'rental', 'road trip car rental', 'Road Trip Car Rental', '{}', 'yes', null, 'Each car shows the kilometres included and the rate for extra ones. Trips outside Ontario need our written consent: ask in your request.', '[{"question": "Can I leave Ontario on a road trip?", "answer": "Only with our written consent. Ask in your request."}]', 660),
  ('ski-trip-car-rental', 'rental', 'ski trip car rental', 'Ski Trip Car Rental', '{"any": [{"classes": ["suv"]}, {"bodies": ["suv"]}]}', 'yes', null, 'SUVs for skis, luggage and winter roads. Winter tires are available as an add-on on the cars that offer them.', '[{"question": "Can I get winter tires?", "answer": "Yes, as an add-on on the cars that offer them. Choose it in your request."}]', 670),
  ('moving-day-car-rental', 'rental', 'moving day car rental', 'Moving Day Car Rental', '{"any": [{"classes": ["van", "suv", "pickup"]}, {"bodies": ["van", "minivan", "suv", "pickup", "truck"]}]}', 'yes', null, 'Vans, minivans and SUVs with room for boxes. Each car''s page shows its seats and its luggage space.', '[{"question": "Do you rent moving trucks?", "answer": "No moving trucks. We rent vans, minivans and SUVs; each car shows its space on its page."}]', 680),
  ('corporate-car-rental', 'rental', 'corporate car rental', 'Corporate Car Rental', '{}', 'yes', null, 'Cars for staff, visitors and projects, delivered to the office or the airport. Receipts for every booking are in your account.', '[{"question": "Can my company pay?", "answer": "Send a request with the company details and we will tell you how to pay and get receipts."}]', 690),
  ('cross-border-car-rental', 'rental', 'cross border car rental', 'Cross Border Car Rental', '{}', 'yes', null, 'Taking a car out of Ontario, the United States included, needs our written consent before the trip. Ask in your request: without that consent, cross-border trips are not allowed.', '[{"question": "Can I drive the car to the United States?", "answer": "Only with our written consent, given before the trip. Ask in your request."}]', 700),
  ('hybrid-car-rental', 'rental', 'hybrid car rental', 'Hybrid Car Rental', '{"fuels": ["hybrid", "plug_in_hybrid"]}', 'yes', null, 'Hybrid and plug-in hybrid cars are listed here when one is in our fleet.', '[{"question": "Do you have hybrids?", "answer": "The hybrids in our fleet today are listed on this page."}]', 710),
  ('electric-car-rental', 'rental', 'electric car rental', 'Electric Car Rental', '{"fuels": ["electric"]}', 'yes', null, 'Electric cars in our fleet, each with its range and charging details on its page.', '[{"question": "How do I charge an electric rental?", "answer": "Each electric car''s page shows its charging details. Ask in your request if you need help with charging."}]', 720),
  ('7-seater-car-rental', 'rental', '7 seater car rental', '7 Seater Car Rental', '{"seats_min": 7}', 'yes', 'minivan', 'Cars with seven or more seats for families and groups.', '[{"question": "Which cars have seven seats?", "answer": "The cars on this page have seven or more seats."}]', 730),
  ('pet-friendly-car-rental', 'rental', 'pet friendly car rental', 'Pet Friendly Car Rental', '{}', 'yes', null, 'Pets are welcome with our approval: mention it in your request. Service animals need no approval. A cleaning fee of {{pet}} applies only if the car comes back with hair, odour or soiling.', '[{"question": "Can I bring my dog?", "answer": "With our approval, yes. Mention it in the request. A pet cleaning fee of {{pet}} applies if the car comes back with hair, odour or soiling."}]', 740),
  ('winter-tires-car-rental', 'rental', 'winter tires car rental', 'Car Rental With Winter Tires', '{}', 'yes', null, 'Winter tires are available as an add-on on the cars that offer them. Choose them in your request.', '[{"question": "Are winter tires included?", "answer": "They are an add-on on the cars that offer them, priced on the car''s page."}]', 750)
